int limit = 3;

auto isBig = [limit](int x) -> bool {
    return x > limit;
};

isBig(5);   // true
isBig(2);   // false

// roughly equivalent:
class Closure {
    int limit;          // captured copy
public:
    Closure(int l) : limit(l) {}
    bool operator()(int x) const {
        return x > limit;
    }
};

auto isBig = Closure(limit);

